@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : int
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + RequestID : int
  + ItemDescription : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteID : int
  + Date : date
}

class ScheduledItem {
  + Dimensions : string
  + Weight : float
}

class DistributionCenter {
  + Address : string
}

class Employee {
  + EmployeeID : int
  + Name : string
}

class Article {
  + RFIDTag : string
  + Category : string
  + Description : string
}

class FoodItem {
  + Description : string
}

class Client {
  + Name : string
  + HomeAddress : string
}

class Category {
  + CategoryName : string
}

City "1" -- "*" H2SLocation
H2SLocation "1" -- "*" DistributionCenter
Resident "1" -- "*" PickupRequest
PickupRequest "1" -- "*" ScheduledItem
Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" ScheduledItem
DistributionCenter "1" -- "*" Article
DistributionCenter "1" -- "*" FoodItem
Employee "1" -- "*" Article
Article "*" -- "1" Category
Client "1" -- "*" Category
Employee "1" -- "*" Client : arrangesDelivery

@enduml

